import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Button } from '@mui/material';
import { TextField } from '@mui/material';
import { Typography } from '@mui/material';
import { Alert, AlertTitle, AlertDescription } from '@mui/material';
import { CircularProgress } from '@mui/material';
import { Box } from '@mui/material';
import { styled } from '@mui/material';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [loginSuccess, setLoginSuccess] = useState(false); // Track login success

    // Clear error message after 5 seconds
    useEffect(() => {
        if (error) {
            const timer = setTimeout(() => setError(''), 5000);
            return () => clearTimeout(timer);
        }
    }, [error]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError(''); // Clear previous errors
        setLoginSuccess(false);

        if (!username || !password) {
            setError('Please enter both username and password.');
            setLoading(false);
            return;
        }

        try {
            // Simulate API call (replace with your actual API endpoint)
            const response = await axios.post('http://localhost:5000/api/login', {  //  <--  CHANGE THIS URL
                username,
                password,
            });

            // In a real app, you'd check the response status and data
            if (response.status === 200 && response.data.success) {
                // Store token and username
                localStorage.setItem('token', response.data.token);
                localStorage.setItem('username', username); // Or get username from response
                setLoginSuccess(true);
                // Redirect to dashboard or home page
                window.location.href = '/dashboard'; //  <--  CHANGE THIS URL
            } else {
                setError(response.data.message || 'Invalid credentials');
            }

        } catch (err) {
            if (err.response) {
                setError(err.response.data.message || 'Login failed');
            } else {
                setError('An unexpected error occurred.');
            }
        } finally {
            setLoading(false);
        }
    };

    // Styled Components (Optional, for more customized styling)
    const StyledLoginContainer = styled(Box)(({ theme }) => ({
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        backgroundColor: theme.palette.grey[100], //light background
        '& .login-card': {
            width: '100%',
            maxWidth: '400px', // Increased max-width for larger screens
            padding: theme.spacing(4), // Increased padding
            backgroundColor: theme.palette.common.white,
            borderRadius: theme.shape.borderRadius,
            boxShadow: theme.shadows[5], // Use a more pronounced shadow
        },
        '& .login-title': {
            marginBottom: theme.spacing(4), // Increased margin
            color: theme.palette.grey[900],  // Darker text
            textAlign: 'center'
        },
        '& .input-field': {
            marginBottom: theme.spacing(3), // Increased margin
        },
        '& .login-button': {
            marginTop: theme.spacing(2),
            width: '100%',
        },
        '& .error-alert': {
            marginTop: theme.spacing(4),
        },
        '& .success-alert': {
            marginTop: theme.spacing(4)
        }
    }));


    return (
        <StyledLoginContainer>
            <div className="login-card">
                <Typography variant="h2" className="login-title">Login</Typography>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <TextField
                        id="username"
                        label="Username"
                        type="text"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        fullWidth
                        placeholder="Enter your username"
                        disabled={loading}
                        className="input-field"
                    />
                    <TextField
                        id="password"
                        label="Password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        fullWidth
                        placeholder="Enter your password"
                        disabled={loading}
                        className="input-field"
                    />
                    <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        className="login-button"
                        disabled={loading}
                    >
                        {loading ? (
                            <>
                                <CircularProgress size={20} style={{ marginRight: 8, color: 'white' }} />
                                Logging in...
                            </>
                        ) : (
                            'Login'
                        )}
                    </Button>
                </form>

                {error && (
                    <Alert severity="error" className="error-alert">
                        <AlertTitle>Error</AlertTitle>
                        <AlertDescription>{error}</AlertDescription>
                    </Alert>
                )}
                {loginSuccess && (
                    <Alert className="success-alert">
                        <AlertTitle>Success</AlertTitle>
                        <AlertDescription>
                            Logged in successfully! Redirecting...
                        </AlertDescription>
                    </Alert>
                )}
            </div>
        </StyledLoginContainer>
    );
};

export default Login;
